public class OptionalBestPractices {

    public record User(String name, Address address) {}
    public record Address(String city) {}

    // Correct usage of flatMap, orElseGet, and avoiding get()
    public String getCityOrDefault(Optional<User> userOpt, String defaultCity) {
        return userOpt
            .flatMap(User::address)
            .map(Address::city)
            .orElseGet(() -> {
                // Lazy execution: only runs if city is missing
                return fetchFallbackCityFromDatabase(defaultCity);
            });
    }

    private String fetchFallbackCityFromDatabase(String fallback) {
        return fallback;
    }
}
